package com.example.examplemod.client.map;

/** Native 16-pixel symbols approved in the atlas preview. No inventory-model rendering. */
public enum AtlasGlyph {
    CITY("................", "......####......", "......#..#......", "......####......", "......#..#......", "..###.####.###..", "..#.#.#..#.#.#..", "..###.#..#.###..", "..#.#.####.#.#..", "..###.#..#.###..", "..#.#.#..#.#.#..", "..###.#..#.###..", "..###.####.###..", "..############..", "................", "................"),
    PLAYER(".......##.......", "......####......", "......####......", ".....######.....", ".....######.....", "....########....", "....########....", "...##########...", "...##########...", "..#####..#####..", "..####....####..", ".####......####.", ".###........###.", "................", "................", "................"),
    STATION("................", "................", "....########....", "...##########...", "..############..", "..#..........#..", "..#..........#..", "..#..........#..", "..#..........#..", "..#..........#..", "..############..", "................", "...##########...", "....##....##....", "................", "................"),
    TRAIN("................", ".....######.....", "....########....", "....##....##....", "....##....##....", "....########....", "....##.##.##....", "....########....", "....#......#....", "....########....", "...##########...", "....##....##....", "...##......##...", "..############..", "................", "................"),
    INDUSTRY("................", "..........##....", "..........##....", "......##..##....", "......##..##....", "......##..##....", "..##..##..##....", "..###.###.####..", "..############..", "..#..#..#..#.#..", "..############..", "..#..#..#..#.#..", "..############..", "..############..", "................", "................"),
    MINE("................", ".....######.....", "....########....", "...##......##...", "..##........##..", "..##..####..##..", "..##..#..#..##..", "..##..#..#..##..", "..##..####..##..", "..##........##..", "..############..", "....##....##....", "...##......##...", "..############..", "................", "................"),
    FREIGHT("................", "......####......", "....###..###....", "..###......###..", "..############..", "..#....##....#..", "..#....##....#..", "..#....##....#..", "..############..", "................", "...##......##...", "..##########.#..", "...##......##...", "................", "................", "................"),
    ENERGY(".........###....", "........###.....", ".......###......", "......###.......", ".....###........", "....########....", "...########.....", "......####......", ".....####.......", "....####........", "....###.........", "...###..........", "..###...........", "..##............", "................", "................"),
    HUB("................", ".......##.......", ".....######.....", "...###....###...", "..############..", "..#..........#..", "..#..##..##..#..", "..#..##..##..#..", "..#..........#..", "..############..", "................", "....#......#....", "..##########....", "....#......#....", "................", "................");

    public static final int SIZE = 16;
    private final int[] rows = new int[SIZE];

    AtlasGlyph(String... pixels) {
        if (pixels.length != SIZE) throw new IllegalArgumentException("Glyph height");
        for (int y = 0; y < SIZE; y++) {
            if (pixels[y].length() != SIZE) throw new IllegalArgumentException("Glyph width");
            for (int x = 0; x < SIZE; x++) {
                char pixel = pixels[y].charAt(x);
                if (pixel != '.' && pixel != '#') throw new IllegalArgumentException("Glyph pixel");
                if (pixel == '#') this.rows[y] |= 1 << x;
            }
        }
    }

    public boolean pixel(int x, int y) {
        return x >= 0 && x < SIZE && y >= 0 && y < SIZE && (this.rows[y] & (1 << x)) != 0;
    }
}
